inputs.script:
let table = base.getTable("Inbox Placement Testing");
let record = await table.selectRecordAsync(input.config().recordId);
let webhook = "https://n8n.dulcy.io/webhook/REDACTED_PATH";

let payload = {};
for (let field of table.fields) {
    payload[field.name] = record.getCellValue(field.name);
}

// Add the recordId to the payload:
payload["recordId"] = record.id;

await fetch(webhook, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
});
